design.compositionCss:
/* After Hours: original cinema-lounge composition, with quiet working surfaces. */
.shell{display:grid;grid-template-columns:222px minmax(0,1fr);gap:0}
.sidebar{display:flex;flex-direction:column;gap:18px;position:sticky;top:0;height:100dvh;padding:28px 16px;border:0;border-right:1px solid var(--weekly-soft);overflow-y:auto}
.brand{margin:0 0 14px;gap:10px;padding:0}
.brand strong{font-family:var(--body);font-size:14px;line-height:1.3;letter-spacing:-.02em}
.brand small{font-size:10px;line-height:1.5}
.sidebar nav{display:grid;grid-template-columns:minmax(0,1fr);gap:5px}
.nav-item{display:flex;flex-direction:row;align-items:center;min-height:46px;padding:11px 12px;gap:12px;border:0;border-radius:9px;font-family:var(--body);font-size:12px;line-height:1.4}
.nav-item span{font-family:var(--body);font-size:10px;letter-spacing:.04em;min-width:19px}
.sidebar-foot{display:grid;grid-template-columns:minmax(0,1fr);margin-top:auto;gap:8px;padding-top:20px;border:0}
.sidebar-foot .quiet{min-width:0;border-radius:8px;text-align:left}
main{max-width:1540px;margin:0 auto;padding:0 38px 72px}
.topbar{min-height:120px;margin-bottom:28px;padding:28px 0;border:0;gap:24px}
.topbar h1{font-family:var(--display);font-size:clamp(27px,3vw,42px);line-height:1.15;letter-spacing:-.05em;max-width:850px}
.topbar .eyebrow{font-size:9px;letter-spacing:.16em;color:var(--weekly-mark)}
.eyebrow{color:var(--weekly-mark)}
.top-actions{gap:12px}
.primary,.quiet{border-radius:8px;min-height:44px;font-size:12px}
.primary{background:var(--acid);color:var(--stage);border-color:var(--acid)}
.quiet{background:var(--panel);color:var(--ink);border-color:var(--weekly-soft)}
.panel,.module,.resource,.phase,.evidence-card,.production,.daily-review,.stat-card:nth-child(n),.cinema-film{border:1px solid var(--weekly-soft);border-radius:16px;box-shadow:none;padding:24px}
.panel h2,.intro-panel h2{font-family:var(--display);font-size:25px;line-height:1.25;letter-spacing:-.045em;border:0;padding-bottom:0}
.panel h3,.module h3{line-height:1.3}
.panel .eyebrow{color:var(--weekly-mark)}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.poster-focus{grid-column:1/-1;min-height:460px;padding:38px;border:1px solid var(--weekly-soft);border-radius:22px}
.poster-focus h2{font-family:var(--display);font-size:clamp(57px,6.4vw,92px);line-height:1.08;letter-spacing:-.06em;max-width:730px;text-decoration:none;margin-bottom:24px}
.poster-focus h2 span{font-family:var(--display);font-style:normal;font-size:1em;line-height:1.1;letter-spacing:-.06em;margin-top:4px}
.poster-focus .hero-script{font-family:var(--script);font-size:30px!important;line-height:1.2;letter-spacing:0;margin:0 0 24px}
.poster-focus .cinema-scene{width:47%;right:0;top:0;bottom:0;opacity:.65;transform:none}
.poster-focus .hero-star{width:52px;height:52px;top:28px;right:25px;border:1px solid var(--weekly-mark);border-radius:50%;background:var(--stage)}
.poster-focus .progress-wrap{max-width:370px;margin-top:28px}
.poster-focus .hero-choices{gap:10px}
.hero-grid .stat-card{grid-column:auto;grid-row:auto;display:flex;flex-direction:column;align-items:start;min-height:120px;padding:22px;border:1px solid var(--weekly-soft);border-radius:14px;background:var(--panel)}
.hero-grid .stat-card strong{font-family:var(--body);font-weight:600;font-size:34px;line-height:1.1;letter-spacing:-.05em;margin:12px 0 5px}
.hero-grid .stat-card span{font-size:10px;line-height:1.5;letter-spacing:.04em}
.hero-grid .stat-card small{font-size:10px;line-height:1.5}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0 32px}
.studio-programme button{border:1px solid var(--weekly-soft)!important;border-radius:14px;min-height:112px;padding:22px!important;background:var(--panel);color:var(--ink);box-shadow:none}
.studio-programme span{font-family:var(--body);font-weight:600;font-size:17px;line-height:1.3;letter-spacing:-.02em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.module h3{font-family:var(--display);font-size:23px;letter-spacing:-.04em}
.module-head small{font-family:var(--body);font-size:11px;font-style:normal;line-height:1.5}
.topic{font-size:13px;line-height:1.6}
.roadmap{display:grid;columns:auto;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.phase:nth-child(n){margin:0!important;min-height:260px;border:1px solid var(--weekly-soft);border-radius:16px;padding:25px}
.phase h3{font-family:var(--display);font-size:22px;line-height:1.3;letter-spacing:-.045em}
.phase small{font-family:var(--body);font-size:10px;letter-spacing:.12em}
.resource-list{grid-template-columns:minmax(0,1fr);gap:14px}
.resource{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr) auto;gap:24px;padding:25px}
.resource h3{font-family:var(--body);font-weight:600;font-size:17px;line-height:1.4;letter-spacing:-.025em}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.evidence-card label{font-family:var(--body);font-size:16px;line-height:1.5}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.cinema-film{padding:24px}
.film-cover{min-height:325px;border:0;border-radius:12px;background:var(--weekly-soft);box-shadow:none}
.cinema-film .film-cover h3{font-family:var(--display);font-size:39px;line-height:1.12;letter-spacing:-.05em}
.film-cover h3 small,.cover-caption{color:var(--ink)}
.cinema-intro{border:1px solid var(--weekly-soft);border-radius:20px;padding:32px}
.cinema-intro h2{font-size:clamp(38px,4vw,58px);line-height:1.15;letter-spacing:-.05em}
.cinema-source-note,.cinema-credits,.meta,.studio-footer{color:var(--ink)}
.journal-masthead{padding:30px 0;border-bottom:1px solid var(--weekly-soft)}
.journal-masthead h2{font-family:var(--display);font-size:clamp(65px,8vw,110px);line-height:1.12;letter-spacing:-.065em}
.journal-masthead h2 em{font-family:var(--script);font-size:.9em;line-height:1.1;letter-spacing:-.04em;font-style:italic;text-decoration:none}
.journal-seal{border:1px solid var(--weekly-mark);border-radius:50%;background:var(--panel);transform:rotate(-8deg)}
.journal-workbench{grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:24px}
.journal-bridge{transform:none}
.journal-section-title{border-top:1px solid var(--weekly-soft)}
.journal-section-title h2{font-family:var(--display);font-size:27px;line-height:1.25;letter-spacing:-.045em}
#view-journal .journal-deck{gap:20px}
.diary-card:not(.poster-card){border:1px solid var(--weekly-soft);border-radius:16px;padding:24px;box-shadow:none;transform:none;margin:0}
#view-journal .diary-card.poster-card{border-radius:14px}
.journal-empty{border-color:var(--weekly-soft);border-radius:16px}
.journal-empty h3{font-size:46px;line-height:1.15}
.form-panel input,.form-panel select,.form-panel textarea,.filter-row input,.filter-row select{border:1px solid var(--weekly-soft);border-radius:8px;background:var(--stage);color:var(--ink)}
.filter-row{border:1px solid var(--weekly-soft);border-radius:12px;background:var(--panel)}
.tag{border-radius:5px}
@media(max-width:1100px) and (min-width:761px){
.shell{grid-template-columns:190px minmax(0,1fr)}
main{padding:0 26px 64px}
.sidebar nav{grid-template-columns:minmax(0,1fr)}
.roadmap{grid-template-columns:repeat(2,minmax(0,1fr))}
.journal-workbench{grid-template-columns:minmax(0,1fr)}
}
@media(max-width:760px){
.shell{display:block}
.sidebar{display:block;position:relative;height:auto;padding:20px;border:0;border-bottom:1px solid var(--weekly-soft)}
.brand{margin:0}
.sidebar-foot{display:flex;flex-wrap:wrap;margin-top:14px;padding:0}
.sidebar-foot .quiet{font-size:10px;padding:10px}
main{padding:0 20px 56px}
.topbar{padding:24px 0;margin-bottom:20px;min-height:0}
.topbar h1{font-size:29px;line-height:1.25;letter-spacing:-.05em}
.top-actions{margin-top:14px}
.poster-focus{min-height:490px;padding:28px 22px;border:1px solid var(--weekly-soft);border-radius:18px}
.poster-focus h2{font-size:clamp(48px,13.3vw,70px);line-height:1.15;letter-spacing:-.065em}
.poster-focus .hero-script{font-size:25px!important}
.poster-focus .cinema-scene{width:80%;right:-20%;opacity:.4}
.poster-focus .hero-star{width:32px;height:32px;top:25px;right:20px}
.hero-grid .stat-card{min-height:120px;padding:16px 10px;border:1px solid var(--weekly-soft);border-radius:12px}
.hero-grid .stat-card strong{font-size:28px;line-height:1.2}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:9px;letter-spacing:0}
.studio-programme,.syllabus-grid,.roadmap,.resource-list,.evidence-grid,.cinema-grid{grid-template-columns:minmax(0,1fr);gap:16px}
.studio-programme button{min-height:96px;padding:22px!important}
.studio-programme span{font-size:17px}
.panel,.module,.resource,.evidence-card,.production,.daily-review,.cinema-film{padding:22px}
.panel h2,.intro-panel h2{font-size:23px;line-height:1.3}
.phase:nth-child(n){min-height:0;padding:24px}
.phase h3{font-size:23px}
.resource{display:block}
.resource h3{font-size:17px}
.film-cover{min-height:280px}
.cinema-film .film-cover h3{font-size:32px;line-height:1.15}
.journal-masthead h2{font-size:clamp(46px,13vw,70px);line-height:1.2;overflow-wrap:anywhere}
.journal-masthead h2 em{font-size:.9em;line-height:1.15}
#view-journal .journal-workbench{grid-template-columns:minmax(0,1fr)}
#view-journal .journal-workbench :is(.form-panel,.journal-bridge){min-width:0;max-width:100%}
#view-journal .journal-workbench :is(form,details,label,small,p,div){min-width:0;max-width:100%;overflow-wrap:anywhere}
#view-journal .form-panel,#view-journal .form-row{grid-template-columns:minmax(0,1fr)}
#view-journal .panel-head{flex-direction:column;align-items:start}
#view-journal .journal-workbench :is(input,select,textarea){min-width:0;max-width:100%;width:100%;box-sizing:border-box}
#view-journal .journal-check input{flex-shrink:0}
#view-journal .journal-workbench :is(button,a){max-width:100%;white-space:normal;overflow-wrap:anywhere}
#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}
#view-journal .diary-card:nth-child(n){transform:none;box-shadow:none}
#view-journal .journal-empty{min-width:0;padding:34px 14px}
#view-journal .journal-empty h3{font-size:38px;overflow-wrap:anywhere}
#view-journal .journal-watch-shelf{min-width:0;overflow-wrap:anywhere}
#view-journal .watch-ticket{flex-wrap:wrap}
}
